// Demo guard: recipients come only from NOTIFY_RECIPIENTS, never from the CSV, and the run is capped.
const limit = Number($env.NOTIFY_LIMIT || 2);
const recipients = ($env.NOTIFY_RECIPIENTS || '').split(',').map((s) => s.trim()).filter(Boolean);
if (!recipients.length) throw new Error('NOTIFY_RECIPIENTS is not set');

const esc = (value) =>
  String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const rate = ({ rate_min: lo, rate_max: hi }) => {
  if (lo == null && hi == null) return 'Rate on request';
  if (lo == null || hi == null || Number(lo) === Number(hi)) return `${Number(lo ?? hi)}% p.a.`;
  return `${Number(lo)}% - ${Number(hi)}% p.a.`;
};

return $input.all().slice(0, limit).map((item, i) => {
  const { user_id, name, products } = item.json;
  const rows = products
    .map((p) => `<tr><td style="padding:8px 12px;border-bottom:1px solid #eee"><strong>${esc(p.product_name)}</strong><br><span style="color:#667">${esc(p.lender)}</span></td><td style="padding:8px 12px;border-bottom:1px solid #eee;white-space:nowrap">${esc(rate(p))}</td></tr>`)
    .join('');
  const html = `<div style="font-family:system-ui,sans-serif;max-width:560px;margin:auto;color:#1c2430">
<h2 style="margin-bottom:4px">Hi ${esc(name)},</h2>
<p>Based on your profile, you may qualify for these personal loans:</p>
<table style="width:100%;border-collapse:collapse">${rows}</table>
<p style="color:#667;font-size:13px;margin-top:24px">Final approval and rates depend on the lender's verification.</p>
<p style="color:#99a;font-size:12px">Demo mode: sent to a test inbox. Intended for ${esc(name)} (user ${esc(user_id.slice(0, 8))}).</p>
</div>`;
  return {
    json: {
      user_id,
      from: $env.SES_FROM,
      to: recipients[i % recipients.length],
      subject: `${products.length} loan offer${products.length > 1 ? 's' : ''} you may qualify for`,
      html,
    },
  };
});

